pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Precondition: caller is NOT the owner so transferOwnership will revert
        vm.assume(caller != c.owner());
        // Record the owner before any calls
        address ownerBefore = c.owner();
        // Call transferOwnership as caller (should revert)
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        // Then call owned() (which also requires owner, will revert if caller is still not owner)
        // But owned() will revert because msg.sender (this contract) is not owner
        // The key: the owner value has not changed because transferOwnership reverted
        address ownerAfter = c.owner();
        // Assert: owner never changed
        assertTrue(ownerAfter == ownerBefore);
    }
}

