pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // First we need to be the owner to call transferOwnership
        // The initial owner is address(0), so we cannot call transferOwnership directly.
        // To set up the test, we can use vm.prank to impersonate the owner,
        // but since owner is address(0), we can first transfer ownership to a known address via the contract itself
        // Since this is a test and we can manipulate the state, we'll use vm.store to set the owner directly
        // because there's no initial owner to call transferOwnership.
        // We set the owner to this contract address to enable calls.
        vm.store(address(c), bytes32(uint256(1)), bytes32(uint256(uint160(address(this))))); // owner is stored at slot 1? Actually slot 0 for address? We'll use a different approach.

        // Simpler: use vm.prank to set msg.sender as newOwner, then call transferOwnership
        vm.prank(newOwner);
        c.transferOwnership(newOwner);

        // Now call owned() which should not change owner to zero
        c.owned();

        // The invariant: owner should still be newOwner, not zero
        assertTrue(c.owner() == newOwner);
    }
}

